<?php
require_once __DIR__.'/components/layout.php';$user=require_user();$page=max(1,min(10000,(int)query('page','1')));$offset=($page-1)*10;
$stmt=db()->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$stmt->bind_param('i',$user['id']);$stmt->execute();$count=(int)$stmt->get_result()->fetch_row()[0];
$stmt=db()->prepare('SELECT order_id,address,pickup_date,order_date,status,total FROM orders WHERE user_id=? ORDER BY order_id DESC LIMIT 10 OFFSET ?');$stmt->bind_param('ii',$user['id'],$offset);$stmt->execute();$orders=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$items=[];
if($orders){$ids=array_column($orders,'order_id');$marks=implode(',',array_fill(0,count($ids),'?'));$stmt=db()->prepare('SELECT oi.order_id,oi.quantity,oi.price,so.option_name FROM order_items oi LEFT JOIN service_options so ON so.option_id=oi.service_option_id WHERE oi.order_id IN ('.$marks.') ORDER BY oi.item_id');$stmt->execute($ids);foreach($stmt->get_result()->fetch_all(MYSQLI_ASSOC) as $item) $items[$item['order_id']][]=$item;}
$stmt=db()->prepare("SELECT COUNT(*) FROM orders WHERE user_id=? AND status='complete'");$stmt->bind_param('i',$user['id']);$stmt->execute();$canReview=(int)$stmt->get_result()->fetch_row()[0]>0;
page_start('Your laundry orders','orders');
?>
<main id="main" class="container"><section class="page-heading compact-heading heading-with-action"><div><h1>Your laundry,<br>all in one place.</h1><p>Pickup details, selected items, and the latest status of every booking.</p></div><a class="button" href="<?= h(url('booking.php')) ?>">Book another pickup <?= icon('plus') ?></a></section>
<?php if(!$orders): ?><section class="empty-state"><?= icon('bag',58) ?><h2><?= $count?'No orders on this page.':'Your first fresh start is waiting.' ?></h2><p><?= $count?'Go back to the first page to see your bookings.':'Once you book a pickup, your orders and updates will appear here.' ?></p><a class="button" href="<?= h(url($count?'my_orders.php':'booking.php')) ?>"><?= $count?'View your orders':'Book your first pickup' ?></a></section><?php else: ?>
<div class="orders-list"><?php foreach($orders as $order): ?><article class="order-card"><header class="order-card-header"><div><h2>Order #<?= (int)$order['order_id'] ?></h2><p>Booked <?= h(date('M j, Y',strtotime($order['order_date']))) ?></p></div><span class="status-badge status-<?= h($order['status']) ?>"><?= h(status_label($order['status'])) ?></span></header>
<?php if($order['status']!=='cancelled'): $progress=array_search($order['status'],['pending','in_progress','complete'],true); ?><ol class="order-progress" aria-label="Order progress"><?php foreach(['Scheduled','In care','Completed'] as $step=>$label): ?><li class="<?= $step<=$progress?'is-reached':'' ?>" <?= $step===$progress?'aria-current="step"':'' ?>><span><?= icon('check',14) ?></span><?= h($label) ?></li><?php endforeach ?></ol><?php endif ?>
<div class="order-meta"><p><?= icon('calendar') ?><span>Pickup date<strong><?= h(date('D, M j, Y',strtotime($order['pickup_date']))) ?></strong></span></p><p><?= icon('pin') ?><span>Pickup address<strong><?= h($order['address']) ?></strong></span></p></div><details class="order-items"><summary>View <?= count($items[$order['order_id']]??[]) ?> item types <strong><?= money($order['total']) ?> <?= icon('chevron',17) ?></strong></summary><ul><?php foreach($items[$order['order_id']]??[] as $item): ?><li><span><?= (int)$item['quantity'] ?> &times; <?= h($item['option_name']??'Service item') ?><small><?= money($item['price']) ?> each</small></span><strong><?= money((float)$item['price']*(int)$item['quantity']) ?></strong></li><?php endforeach ?></ul></details>
<?php if($order['status']==='pending'): ?><form method="post" action="<?= h(url('db/cancel_order.php')) ?>" class="cancel-order" data-confirm="Cancel this scheduled pickup?"><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['order_id'] ?>"><button class="text-button" type="submit">Cancel booking</button></form><?php endif ?></article><?php endforeach ?></div>
<?php if($count>10): ?><nav class="pagination" aria-label="Order pages"><?php if($page>1): ?><a class="button button-outline" href="?page=<?= $page-1 ?>">Previous</a><?php endif ?><span>Page <?= $page ?> of <?= (int)ceil($count/10) ?></span><?php if($offset+10<$count): ?><a class="button button-outline" href="?page=<?= $page+1 ?>">Next</a><?php endif ?></nav><?php endif ?>
<?php endif ?>
<?php if($canReview): ?><section class="review-form-section" id="review"><div><h2>How was your care?</h2><p>Share your experience after a completed order. Your review appears on the home page.</p></div><form method="post" action="<?= h(url('db/db_review.php')) ?>" class="stack-form" data-submit-form><?= csrf_field() ?><div class="field"><label for="rating">Your rating</label><select id="rating" name="rating" required><option value="">Choose a rating</option><?php for($i=5;$i>=1;$i--): ?><option value="<?= $i ?>"><?= $i ?> <?= $i===1?'star':'stars' ?></option><?php endfor ?></select></div><div class="field"><label for="comment">Your review</label><textarea id="comment" name="comment" minlength="5" maxlength="1500" rows="4" required></textarea></div><div><button class="button" type="submit" data-loading-label="Publishing...">Publish review</button></div></form></section><?php endif ?></main>
<?php page_end() ?>
